      "callObjectionPhrases": "\\b(concern|worried|not sure|too expensive|budget|price|pricing|timing|procurement|security review|legal review|need to think|another vendor)\\b",
      "callCompetitorPhrases": "\\b(competitor|alternative|evaluating|looked at|using|salesforce|hubspot|gong|chorus|clari|outreach|salesloft|6sense|demandbase|clay|zapier|workato)\\b",
      "callNextStepPhrases": "\\b(next step|follow up|send over|circle back|schedule|book|meet again|by (monday|tuesday|wednesday|thursday|friday)|action item|I'll send|we'll send)\\b",
      "callFeaturePhrases": "\\b(wish|would love|need it to|feature|capability|does it support|can it|integration|custom field|dashboard|report|export|import)\\b",
      "callPricingPhrases": "\\b(price|pricing|budget|cost|discount|contract|renewal|procurement|purchase order|PO|invoice|annual|monthly|ARR|MRR|\\$\\d+)\\b",
      "callCriteriaPhrases": "\\b(criteria|decision|evaluate|evaluation|success looks like|requirements|must have|need to see|stakeholder|committee|approve|approval)\\b",
      "callRiskPhrases": "\\b(delay|blocked|risk|concern|not a priority|no budget|push|slip|stalled|ghost|unresponsive|champion left|reorg)\\b",
      "callFillerPhrases": "\\b(let me tell you|obviously|basically|trust me|to be honest|just checking in|does that make sense\\?)\\b",
